const loginForm=document.querySelector("#loginForm"),loginStatus=document.querySelector("#loginStatus");function setLoginStatus(t,n=!1){loginStatus&&(loginStatus.textContent=t,loginStatus.classList.toggle("is-error",n))}async function checkSession(){const t=await fetch("/api/admin/session",{credentials:"same-origin"});(await t.json()).authenticated&&(window.location.href="/admin.html")}loginForm?.addEventListener("submit",async t=>{t.preventDefault(),setLoginStatus("Validando acceso...");const n=Object.fromEntries(new FormData(loginForm).entries());try{const t=await fetch("/api/admin/login",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)}),o=await t.json().catch(()=>({}));if(!t.ok)throw new Error(o.error||"No se pudo iniciar sesion.");window.location.href="/admin.html"}catch(t){setLoginStatus(t.message,!0)}}),checkSession().catch(()=>{setLoginStatus("")});
